import styles from './index.module.scss';
import { memo, useEffect, useRef, useState } from 'react';

const CardItems = ({ list, cardSize, $onSelectCard }) => {
    const removeList = useRef([]); // 删除的卡片列表
    const onChangeCard = (e, i) => { // 点击卡片
        if (e.currentTarget.className.indexOf('visible') !== -1) { // 没遮挡
            $onSelectCard.emit({
                card: { ...list[i] },
                callback() {
                    removeList.current.push(list[i]);
                    e.currentTarget.style.display = 'none';
                    removeList.current.length === list.length && alert('你成功了！');
                },
            });
        }
    };
    useEffect(() => { // 监听卡片是否被遮挡
        document.querySelectorAll('.card-img').forEach(ele => {
            const io = new IntersectionObserver((data) => { //* 判断是否被遮挡
                if (data[0].isVisible === false) {
                    data[0].target.parentNode.classList.add('mask');
                } else {
                    data[0].target.parentNode.classList.remove('mask');
                    data[0].target.parentNode.classList.add('visible');
                    io.unobserve(data[0].target);
                }
            }, {
                threshold: [1, 0],
                delay: 100,
                trackVisibility: true,
            });
            io.observe(ele);
        });
    }, [list]);
    return (
        <>
            {
                list.map((item, i) => (
                    <div
                        className={`${styles.card} card-item`}
                        key={i}
                        onClick={e => onChangeCard(e, i)}
                        style={{ left: item.x, top: item.y, width: cardSize, height: cardSize }}
                    >
                        <div className={`${styles.imgBox} w-full h-full card-img`}>
                            <img
                                alt={item.name}
                                className={styles.img}
                                src={item.img}
                            />
                        </div>
                    </div>
                ))
            }
        </>
    );
};

export default memo(CardItems);
