import {
    generateHTMLTable,
    generateExcel,
} from 'json5-to-table';
import { useState } from 'react';
import { Button, Input, Space } from 'antd';
import { DownloadOutlined } from '@ant-design/icons';
import style from './index.module.scss';

const { TextArea } = Input;

const JsonToTable = () => {
    const [jsonStr, setJsonStr] = useState({}); // 输入内容 json字符串
    const [domStr, setDomStr] = useState(null); // 生成的dom字符串

    const onGenerateTable = () => { // 转换为表格
        try {
            const res = eval(`[${jsonStr}]`)[0];
            setDomStr(generateHTMLTable(res.data, res.schema, {}));
        } catch (e) {
            alert('请输入正确的json字符串');
        }
    };
    const onGenerateExcel = () => { // 下载excel
        try {
            const res = eval(`[${jsonStr}]`)[0];
            setDomStr(generateHTMLTable(res.data, res.schema, {}));
            generateExcel(res.data, res.schema, { writeTo: '数据.xlsx' });
        } catch (e) {
            alert('请输入正确的json字符串');
        }
    };

    return (
        <div className="d-flex p-20 h-full">
            <div className="u-1of2 p-r-10 d-flex ">
                <TextArea
                    onChange={e => setJsonStr(e.target.value)}
                    placeholder="请输入数据，例如： { data: [ { name: 'Jim' } ], schema: [ { title: 'Name', path: 'name' } ] }"
                />
            </div>
            <div className="u-1of2 p-l-10">
                <div className='m-b-20'>
                    <Space>
                        <Button onClick={onGenerateTable} type="primary">转换为表格</Button>
                        <Button icon={<DownloadOutlined />} onClick={onGenerateExcel}>下载excel</Button>
                    </Space>
                </div>
                <div dangerouslySetInnerHTML={{ __html: domStr }} />
            </div>
        </div>
    );
};

export default JsonToTable;
