import { useEffect, useRef } from 'react';
import * as echarts from 'echarts';
import { useSize } from 'ahooks';

const colors = ['rgba(1,48,203,0.6)', 'rgb(255,2,2,0.6)'];
const option = {
    grid: {
        left: 50,
    },
    legend: {},
    tooltip: {
        show: true,
        formatter: '{a}: <br/>  时间音高:{c}',
    },
    color: colors,
    dataZoom: [
        {
            show: true,
            start: 0,
            end: 100,
        },
        {
            show: true,
            yAxisIndex: 0,
            filterMode: 'empty',
            width: 30,
            height: '80%',
            showDataShadow: false,
            left: '94%',
        },
    ],
    xAxis: [{
        max: (value) => value.max + 1000,
        min: (value) => value.min - 1000,
        name: 'Mid 时间',
        axisLabel: {
            textStyle: {
                color: colors[0],
            },
        },
    }, {
        min: (value) => value.min - 1000,
        max: (value) => value.max + 1000,
        name: 'Json 时间',
        axisLabel: {
            textStyle: {
                color: colors[1],
            },
        },
    }],
    yAxis: [
        {
            // max: 130,
            minInterval: 1,
            type: 'value',
            name: '音高',
            // splitNumber: 131,
            nameTextStyle: {
                padding: [0, 0, 10, 0],
            },
        },
    ],
    series: [
        {
            name: 'Mid音符',
            type: 'scatter',
            smooth: true,
            emphasis: {
                focus: 'series',
            },
            data: [],
        },
        {
            name: 'Json音符',
            type: 'scatter',
            xAxisIndex: 1,
            smooth: true,
            emphasis: {
                focus: 'series',
            },
            data: [],
        },
    ],
};

const LineEcharts = ({ dataSource }) => {
    const chartRef = useRef(null);
    const myChart = useRef(null);

    useEffect(() => {
        // 初始化
        myChart.current = echarts.init(chartRef.current);
    }, []);
    useEffect(() => {
        option.series[0].data = dataSource?.mid?.map((item) => [item.start_time, item.midi]);
        option.series[1].data = dataSource?.json?.map((item) => [item.start_time, item.note_idx]);
        // 绘制图表
        myChart.current.setOption(option);
    }, [dataSource]);

    const chartSize = useSize(chartRef);
    useEffect(() => { // 监听chart容器大小变化
        myChart.current && myChart.current.resize();
    }, [chartSize]);
    return (
        <div>
            <div className='fz-22 m-t-30'>对比图:</div>
            <div ref={chartRef} style={{ height: 600 }}>

            </div>
        </div>
    );
};

export default LineEcharts;
