// 卡片类型
import { useEffect, useState } from 'react';
import banana from '../../../assets/game/banana.png';
import durian from '../../../assets/game/durian.png';
import apple from '../../../assets/game/apple.png';
import orange from '../../../assets/game/orange.png';
import peach from '../../../assets/game/peach.png';
import grape from '../../../assets/game/grape.png';
import lemon from '../../../assets/game/lemon.png';
import ananas from '../../../assets/game/ananas.png';
import pitaya from '../../../assets/game/pitaya.png';
import watermelon from '../../../assets/game/watermelon.png';
import cherry from '../../../assets/game/cherry.png';
import pear from '../../../assets/game/pear.png';

// 卡片类型
const cardTypes = [
    { name: '香蕉', img: banana },
    { name: '榴莲', img: durian },
    { name: '苹果', img: apple },
    { name: '橙子', img: orange },
    { name: '桃子', img: peach },
    { name: '葡萄', img: grape },
    { name: '柠檬', img: lemon },
    { name: '菠萝', img: ananas },
    { name: '火龙果', img: pitaya },
    { name: '西瓜', img: watermelon },
    { name: '樱桃', img: cherry },
    { name: '梨', img: pear },
];
// 卡片组数
const cardNum = 30; // 3的倍数

/**
 * 生成卡片数据
 * @param {Array} arr 卡片类型
 * 卡片类型长度为6，每个类型有9个
 */
const generateList = (arr, w, h) => {
    let a, b, c, d, e, f, g, k, l, m, n, o;// 计数
    a = b = c = d = e = f = g = k = l = m = n = o = 0; // 初始化计数
    const array = [];// 存放打乱后的图块
    for (let i = 0; i < arr.length; i++) { // 打乱图块
        for (let j = 0; j < cardNum; j++) {
            const x = parseInt(Math.random() * arr.length);
            switch (x) {
                case 0: if (a !== cardNum) { array.push(arr[x]); a++ } break;
                case 1: if (b !== cardNum) { array.push(arr[x]); b++ } break;
                case 2: if (c !== cardNum) { array.push(arr[x]); c++ } break;
                case 3: if (d !== cardNum) { array.push(arr[x]); d++ } break;
                case 4: if (e !== cardNum) { array.push(arr[x]); e++ } break;
                case 5: if (f !== cardNum) { array.push(arr[x]); f++ } break;
                case 6: if (g !== cardNum) { array.push(arr[x]); g++ } break;
                case 7: if (k !== cardNum) { array.push(arr[x]); k++ } break;
                case 8: if (l !== cardNum) { array.push(arr[x]); l++ } break;
                case 9: if (m !== cardNum) { array.push(arr[x]); m++ } break;
                case 10: if (n !== cardNum) { array.push(arr[x]); n++ } break;
                case 11: if (o !== cardNum) { array.push(arr[x]); o++ } break;
                default: break;
            }
        }
    }
    if (a !== cardNum) { let i = cardNum - a; while (i !== 0) { array.push(arr[0]); i-- } }// 判断是否有图块没达到3组（3*3），如没达到则对应补满
    if (b !== cardNum) { let i = cardNum - b; while (i !== 0) { array.push(arr[1]); i-- } }
    if (c !== cardNum) { let i = cardNum - c; while (i !== 0) { array.push(arr[2]); i-- } }
    if (d !== cardNum) { let i = cardNum - d; while (i !== 0) { array.push(arr[3]); i-- } }
    if (e !== cardNum) { let i = cardNum - e; while (i !== 0) { array.push(arr[4]); i-- } }
    if (f !== cardNum) { let i = cardNum - f; while (i !== 0) { array.push(arr[5]); i-- } }
    if (g !== cardNum) { let i = cardNum - g; while (i !== 0) { array.push(arr[6]); i-- } }
    if (k !== cardNum) { let i = cardNum - k; while (i !== 0) { array.push(arr[7]); i-- } }
    if (l !== cardNum) { let i = cardNum - l; while (i !== 0) { array.push(arr[8]); i-- } }
    if (m !== cardNum) { let i = cardNum - m; while (i !== 0) { array.push(arr[9]); i-- } }
    if (n !== cardNum) { let i = cardNum - n; while (i !== 0) { array.push(arr[10]); i-- } }
    if (o !== cardNum) { let i = cardNum - o; while (i !== 0) { array.push(arr[11]); i-- } }
    return array.map(item => ({ ...item, x: parseInt(Math.random() * w), y: parseInt(Math.random() * h) }));
};

// 生成卡片数据 hook
const useGenerateData = (w, h) => {
    const [list, setList] = useState([]);// 卡片数据
    useEffect(() => {
        setList(generateList(cardTypes, w, h));
    }, []);
    return {
        onReload: () => setList(generateList(cardTypes, w, h)), // 重新生成卡片数据
        cardList: list, // 卡片数据
    };
};

export default useGenerateData;
