import { useState } from 'react';
import { useEventEmitter } from 'ahooks';

// 选中卡片 hook
const useSelectCard = () => {
    const [currentCards, setCurrentCards] = useState([]); // 当前卡片
    const $onSelectCard = useEventEmitter();
    $onSelectCard.useSubscription(({ card, callback }) => {
        if (!card) {
            setCurrentCards([]);
            return;
        }
        const newList = [...currentCards];
        if (newList.filter(item => item.name === card.name).length === 2) { // 三个消除
            setCurrentCards(newList.filter(item => item.name !== card.name));
        } else {
            if (newList.length === 5) { // 超过5个就失败了
                alert('你失败了，请刷新页面重来！');
                return;
            }
            setCurrentCards([...newList, card]);
        }
        callback && callback();
    });

    return {
        currentCards,
        $onSelectCard,
    };
};

export default useSelectCard;
