import { Table, theme } from 'antd';
import classNames from 'classnames';
import ResizeObserver from 'rc-resize-observer';
import { useEffect, useRef, useState } from 'react';
import { VariableSizeGrid as Grid } from 'react-window';
import './index.module.scss';

const columns = [
    {
        title: '序号',
        dataIndex: 'index',
        width: 70,
        render: (value, row, index) => index + 1,
    },
    {
        title: '时间（秒）',
        dataIndex: 'midTime',
        width: 160,
        render: (value, row, index) => row.mid?.time,
    },
    {
        title: '结果',
        width: 120,
        dataIndex: 'status',
        onFilter: (value, record) => {
            if (value === 1) {
                return !record.json && record.mid;
            } else if (value === 2) {
                return record.json && !record.mid;
            } else {
                return record.json && record.mid;
            }
        },
        render: (value, row, index) => {
            let i = 0;
            if (!row.json && row.mid) {
                i = 1;
            }
            if (row.json && !row.mid) {
                i = 2;
            }
            return [
                <span className="color-success" key={0}>正确</span>,
                <span className="color-error" key={1}>少弹</span>,
                <span className="color-error" key={2}>多弹</span>,
            ][i];
        },
        filters: [
            {
                text: '正确',
                value: 0,
            },
            {
                text: '少弹',
                value: 1,
            },
            {
                text: '多弹',
                value: 2,
            },
        ],
    },
    {
        title: 'Mid音符',
        render: (value, row) => {
            return row.mid ? (<span>音高{row.mid.midi}（{(row.mid.name)}）</span>) : '无';
        },
        width: 450,
    },
    {
        title: 'JSON音符',
        dataIndex: 'jsonNote',
        width: window.innerWidth - 1000,
        render: (value, row) => {
            if (row.json) {
                return (<span>音高{row.json.note_idx}（{((row.json.score || 0) * 100).toFixed(2)}%）</span>);
            }
            return '无';
        },
    },
    {
        title: 'start_time',
        dataIndex: 'jsonTime',
        width: 150,
        render: (value, row, index) => row.json?.start_time,
    },
];
const VirtualTable = (props) => {
    const { scroll } = props;
    const [tableWidth, setTableWidth] = useState(0);
    const { token } = theme.useToken();
    const widthColumnCount = columns.filter(({ width }) => !width).length;
    const mergedColumns = columns.map((column) => {
        if (column.width) {
            return column;
        }
        return {
            ...column,
            width: Math.floor(tableWidth / widthColumnCount),
        };
    });
    const gridRef = useRef();
    const [connectObject] = useState(() => {
        const obj = {};
        Object.defineProperty(obj, 'scrollLeft', {
            get: () => {
                if (gridRef.current) {
                    return gridRef.current?.state?.scrollLeft;
                }
                return null;
            },
            set: (scrollLeft) => {
                if (gridRef.current) {
                    gridRef.current.scrollTo({
                        scrollLeft,
                    });
                }
            },
        });
        return obj;
    });
    const resetVirtualGrid = () => {
        gridRef.current?.resetAfterIndices({
            columnIndex: 0,
            shouldForceUpdate: true,
        });
    };
    useEffect(() => resetVirtualGrid, [tableWidth]);
    const renderVirtualList = (rawData, { scrollbarSize, ref, onScroll }) => {
        ref.current = connectObject;
        const totalHeight = rawData.length * 54;
        return (
            <Grid
                className="virtual-grid"
                columnCount={mergedColumns.length}
                columnWidth={(index) => {
                    const { width } = mergedColumns[index];
                    return totalHeight > scroll?.y && index === mergedColumns.length - 1 ?
                        width - scrollbarSize - 1 :
                        width;
                }}
                height={scroll.y}
                onScroll={({ scrollLeft }) => {
                    onScroll({
                        scrollLeft,
                    });
                }}
                ref={gridRef}
                rowCount={rawData.length}
                rowHeight={() => 54}
                width={tableWidth}
            >
                {({ columnIndex, rowIndex, style }) => (
                    <div
                        className={classNames('virtual-table-cell', {
                            'virtual-table-cell-last': columnIndex === mergedColumns.length - 1,
                        })}
                        style={{
                            ...style,
                            boxSizing: 'border-box',
                            padding: token.padding,
                            borderBottom: `${token.lineWidth}px ${token.lineType} ${token.colorSplit}`,
                            background: token.colorBgContainer,
                        }}
                    >
                        {mergedColumns[columnIndex].render ?
                            mergedColumns[columnIndex].render(rawData[rowIndex][mergedColumns[columnIndex].dataIndex], rawData[rowIndex], rowIndex) :
                            rawData[rowIndex][mergedColumns[columnIndex].dataIndex]}
                    </div>
                )}
            </Grid>
        );
    };
    return (
        <ResizeObserver
            onResize={({ width }) => {
                setTableWidth(width);
            }}
        >
            <Table
                {...props}
                columns={mergedColumns}
                components={{
                    body: renderVirtualList,
                }}
                pagination={false}
            />
        </ResizeObserver>
    );
};

export default VirtualTable;
