import { getDiffResult } from './needleman-wunsch';
import { Alert, Button, Input, InputNumber, message, Select, Space, Upload } from 'antd';
import { CopyOutlined, PlusOutlined } from '@ant-design/icons';
import style from './index.module.scss';
import { useState } from 'react';
import { getJsonInfo, getMidiInfo } from '../../utils/mid-diff-new';
import VirtualTable2 from './VirtualTable';
import { CopyToClipboard } from 'react-copy-to-clipboard';

// 内德勒曼-温施算法对比
const MidWunschDiff = () => {
    const [messageApi, contextHolder] = message.useMessage(); // message
    // mid文件
    const [midFile, setMidFile] = useState(null);
    // json文件
    const [jsonFile, setJsonFile] = useState(null);
    // json文件地址
    const [jsonUrl, setJsonUrl] = useState(null);
    // 表格数据
    const [list, setList] = useState([]);
    const [rateInfo, setRateInfo] = useState({});
    // 开始对比
    const onDiff = () => {
        const midFileSuffix = midFile?.name.substring(midFile?.name.lastIndexOf('.') + 1);
        if (!midFile || (midFileSuffix !== 'mid')) {
            messageApi.error({
                key: 'midFile',
                content: '请选择mid文件',
            });
            return;
        }
        const jsonFileSuffix = jsonFile?.name.substring(jsonFile?.name.lastIndexOf('.') + 1);
        if (!jsonFile || (jsonFileSuffix !== 'json')) { // json文件和地址二选一
            if (!jsonUrl) {
                messageApi.error({
                    key: 'jsonFile',
                    content: '请选择json文件或输入json地址',
                });
                return;
            }
        }
        Promise.all([
            // 获取midi信息
            new Promise(resolve => {
                getMidiInfo(window.webkitURL.createObjectURL(midFile), 0, 0).then(res => {
                    resolve(res);
                }).catch(() => {
                    messageApi.error({
                        key: 'midFile',
                        content: 'mid文件解析失败',
                    });
                });
            }),
            // 获取json信息
            new Promise(resolve => {
                getJsonInfo(jsonFile ? window.webkitURL.createObjectURL(jsonFile) : jsonUrl, 0).then((res) => {
                    resolve(res);
                }).catch(() => {
                    messageApi.error({
                        key: 'jsonFile',
                        content: 'json文件解析失败',
                    });
                });
            }),
        ]).then(([midData, jsonData]) => { // mid json对比计算
            const res = getDiffResult(midData.notes.map(({ midi }) => midi), jsonData.notes.map(({ note_idx }) => note_idx));
            console.log(res);
            let index = -1;
            const midList = res[0].split(',').map((id, i) => {
                if (id !== '-') {
                    index++;
                    return midData.notes[index];
                }
            });
            index = -1;
            const jsonList = res[1].split(',').map((id, i) => {
                if (id !== '-') {
                    index++;
                    return jsonData.notes[index];
                }
            });
            const rateInfo = {
                correctNum: 0,
                lessNum: 0,
                moreNum: 0,
            };
            setList(new Array(midList.length).fill(0).map((_, index) => {
                if (midList[index] && jsonList[index]) {
                    rateInfo.correctNum++;
                } else if (midList[index] && !jsonList[index]) {
                    rateInfo.lessNum++;
                } else if (!midList[index] && jsonList[index]) {
                    rateInfo.moreNum++;
                }
                return {
                    mid: midList[index],
                    json: jsonList[index],
                };
            }));
            setRateInfo({
                ...rateInfo,
                correctRate: (rateInfo.correctNum * 100 / midList.length).toFixed(2),
                lessRate: (rateInfo.lessNum * 100 / midList.length).toFixed(2),
                moreRate: (rateInfo.moreNum * 100 / midList.length).toFixed(2),
            });
        });
    };
    console.log(list);

    // 复制提示
    const copyTips = (e) => {
        messageApi.success({
            key: 'copy',
            content: '复制成功！',
        });
    };
    // 全部内容
    const copyAllText = `${
        rateInfo.correctNum ? `正确率：${rateInfo.correctRate}%（${rateInfo.correctNum}个）` : ''
    }${
        rateInfo.lessNum ? `\n少弹率：${rateInfo.lessRate}%（${rateInfo.lessNum}个）` : ''
    }${
        rateInfo.moreNum ? `\n多弹率：${rateInfo.moreRate}%（${rateInfo.moreNum}个）` : ''
    }`;
    const resultNumRate = list.length ? (
        <Space
            style={{
                width: '100%',
            }}
        >
            {
                rateInfo.correctNum ?
                    <Alert message={
                        <>
                            正确率：{rateInfo.correctRate}%（{rateInfo.correctNum}个）
                            <CopyToClipboard
                                onCopy={copyTips}
                                text={`${rateInfo.correctRate}%`}
                            >
                                <a className='p-x-10' type="link"><CopyOutlined /></a>
                            </CopyToClipboard>
                        </>
                    } type="success"
                    /> : null
            }
            {
                rateInfo.lessNum ?
                    <Alert message={
                        <>
                            少弹率：{rateInfo.lessRate}%（{rateInfo.lessNum}个）
                            <CopyToClipboard
                                onCopy={copyTips}
                                text={`${rateInfo.lessRate}%`}
                            >
                                <a className='p-x-10' type="link"><CopyOutlined /></a>
                            </CopyToClipboard>
                        </>
                    } type="error"
                    /> : null
            }
            {
                rateInfo.moreNum ?
                    <Alert message={
                        <>
                            多弹率：{rateInfo.moreRate}%（{rateInfo.moreNum}个）
                            <CopyToClipboard
                                onCopy={copyTips}
                                text={`${rateInfo.moreRate}%`}
                            >
                                <a className='p-x-10' type="link"><CopyOutlined /></a>
                            </CopyToClipboard>
                        </>
                    } type="error"
                    /> : null
            }
            {
                rateInfo.correctNum ?
                    <CopyToClipboard
                        onCopy={copyTips}
                        text={copyAllText}
                    >
                        <a className='p-x-10' type="link"><CopyOutlined /> 复制全部</a>
                    </CopyToClipboard> : null
            }
        </Space>
    ) : null;
    return (
        <div className='p-20'>
            {contextHolder}
            <div className="d-flex flex-wrap">
                <Upload
                    accept={'.mid'}
                    beforeUpload={file => {
                        setMidFile(file);
                        return false;
                    }}
                    className='m-r-20'
                    fileList={midFile ? [midFile] : []}
                    maxCount={1}
                    onRemove={() => setMidFile(null)}
                >
                    <Button icon={<PlusOutlined />} type="dashed">选择mid文件</Button>
                </Upload>
                <Upload
                    accept={'.json'}
                    beforeUpload={file => {
                        setJsonFile(file);
                        return false;
                    }}
                    fileList={jsonFile ? [jsonFile] : []}
                    maxCount={1}
                    onRemove={() => setJsonFile(null)}
                >
                    <Button icon={<PlusOutlined />} type="dashed">选择json文件</Button>
                </Upload>
                <div className={style.input}>
                    <Input.TextArea onChange={e => setJsonUrl(e.target.value)} placeholder="请输入json地址(json文件和地址二选一)"/>
                </div>
                <div className='flex-1 d-flex justify-content-end'>
                    <Button onClick={onDiff} type='primary'>开始对比计算</Button>
                </div>
            </div>
            <div className='m-t-50 p-t-30' style={{ borderTop: '2px solid #eee' }}>
                <div className='m-b-20 fz-24'>对比计算结果：</div>
                {resultNumRate}
            </div>
            {/* mid json对比table*/}
            <div className='m-t-30'>
                <VirtualTable2
                    dataSource={list}
                    scroll={{
                        y: 500,
                        x: 'max-content',
                    }}
                />

            </div>
        </div>
    );
};

export default MidWunschDiff;
