import useGenerateData from './hooks/useGenerateData';
import styles from './index.module.scss';
import CardItems from './CardItems';
import useSelectCard from './hooks/useSelectCard';
import { useEventEmitter } from 'ahooks';
import { Button } from 'antd';
const GameSheep = () => {
    const cardSize = 50;
    const { cardList, onReload } = useGenerateData(500 - cardSize, 500 - cardSize); // 生成卡片数据
    const { currentCards, $onSelectCard } = useSelectCard(); // 选择卡片
    const onReopen = () => { // 重开
        onReload();
        $onSelectCard.emit({ card: null });
    };
    return (
        <div className={styles.page}>
            <div className={styles.cardBox}>
                <CardItems $onSelectCard={$onSelectCard} cardSize={cardSize} list={cardList} />
            </div>
            <div className={styles.controlBox}>
                <div className={styles.currentList}>
                    {
                        currentCards.map((item, i) => (
                            <div className={styles.card} key={i}>
                                <img
                                    alt={item.name}
                                    className={styles.img}
                                    src={item.img}
                                />
                            </div>
                        ))
                    }
                </div>
                <div className={styles.btns}>
                    <Button onClick={onReopen}>重开</Button>
                </div>
            </div>
        </div>
    );
};

export default GameSheep;
