import { Midi } from '@tonejs/midi';
import { useState } from 'react';
import VirtualTable from './VirtualTable';
import VirtualTable2 from './VirtualTable2';
import { Button, Upload, message, Select, Alert, Space, Input } from 'antd';
import { PlusOutlined, CopyOutlined } from '@ant-design/icons';
import {
    getMidiInfo,
    getJsonInfo,
    diffMidJson,
    diffList,
    getMidiInfo2,
    getJsonInfo2,
    handleJsonLess,
    diffJsonMidTime,
} from '../../utils/mid-diff';
import LineEcharts from './LineEcharts';
import style from './index.module.scss';
import { CopyToClipboard } from 'react-copy-to-clipboard';

const diffTimeList = Array.from(Array(Math.ceil(21)), (v, k) => ({
    value: k * 10,
    label: `${k * 10} ms`,
}));

const MidDiff = () => {
    const [messageApi, contextHolder] = message.useMessage(); // message
    // midi信息
    const [midiList, setMidiList] = useState([]);
    const [midiList2, setMidiList2] = useState([]);
    // midi 比率信息
    const [midiRateInfo, setMidiRateInfo] = useState({
        correctNum: null, // 正确数
        errNum: null, // 错误数
        moreNum: null, // 多弹数
        lessNum: null, // 少弹数
        correctRate: null, // 正确率
        errRate: null, // 错误率
        moreRate: null, // 多弹率
        lessRate: null, // 少弹率
    });

    // mid文件
    const [midFile, setMidFile] = useState(null);
    // json文件
    const [jsonFile, setJsonFile] = useState(null);
    // json文件地址
    const [jsonUrl, setJsonUrl] = useState(null);

    // 音符相差时间
    const [diffTime, setDiffTime] = useState(30);

    // charts list
    const [chartData, setChartData] = useState({});
    // 开始对比
    const onDiff = () => {
        const midFileSuffix = midFile?.name.substring(midFile?.name.lastIndexOf('.') + 1);
        if (!midFile || (midFileSuffix !== 'mid')) {
            messageApi.error({
                key: 'midFile',
                content: '请选择mid文件',
            });
            return;
        }
        const jsonFileSuffix = jsonFile?.name.substring(jsonFile?.name.lastIndexOf('.') + 1);
        if (!jsonFile || (jsonFileSuffix !== 'json')) { // json文件和地址二选一
            if (!jsonUrl) {
                messageApi.error({
                    key: 'jsonFile',
                    content: '请选择json文件或输入json地址',
                });
                return;
            }
        }
        Promise.all([
            // 获取midi信息
            new Promise(resolve => {
                getMidiInfo(window.webkitURL.createObjectURL(midFile), diffTime).then(res => {
                    resolve(res);
                }).catch(() => {
                    messageApi.error({
                        key: 'midFile',
                        content: 'mid文件解析失败',
                    });
                });
            }),
            // 获取json信息
            new Promise(resolve => {
                getJsonInfo(jsonFile ? window.webkitURL.createObjectURL(jsonFile) : jsonUrl, diffTime).then((res) => {
                    resolve(res);
                }).catch(() => {
                    messageApi.error({
                        key: 'jsonFile',
                        content: 'json文件解析失败',
                    });
                });
            }),
        ]).then(([midData, jsonData]) => { // mid json对比计算
            // handleJsonLess(midData.result, jsonData.result); // json少弹处理
            const { list, rate } = diffMidJson(midData.result, jsonData.result); // mid和json 对比计算
            setMidiRateInfo(rate);
            setMidiList(list);
            setChartData({
                mid: midData.notes,
                json: jsonData.notes,
            });
            setMidiList2(diffJsonMidTime(midData.notes, jsonData.notes, diffTime));
        });
    };
    // 复制提示
    const copyTips = (e) => {
        messageApi.success({
            key: 'copy',
            content: '复制成功！',
        });
    };
    // 全部内容
    const copyAllText = `${
        midiRateInfo.correctNum ? `正确率：${midiRateInfo.correctRate}%（${midiRateInfo.correctNum}个）` : ''
    }${
        midiRateInfo.lessNum ? `少弹率：${midiRateInfo.lessRate}%（${midiRateInfo.lessNum}个）` : ''
    }${
        midiRateInfo.moreNum ? `多弹率：${midiRateInfo.moreRate}%（${midiRateInfo.moreNum}个）` : ''
    }`;

    const resultNumRate = midiList.length ? (
        <Space
            style={{
                width: '100%',
            }}
        >
            {
                midiRateInfo.correctNum ?
                    <Alert message={
                        <>
                                正确率：{midiRateInfo.correctRate}%（{midiRateInfo.correctNum}个）
                            <CopyToClipboard
                                onCopy={copyTips}
                                text={`${midiRateInfo.correctRate}%`}
                            >
                                <a className='p-x-10' type="link"><CopyOutlined /></a>
                            </CopyToClipboard>
                        </>
                    } type="success"
                    /> : null
            }
            {
                midiRateInfo.lessNum ?
                    <Alert message={
                        <>
                                少弹率：{midiRateInfo.lessRate}%（{midiRateInfo.lessNum}个）
                            <CopyToClipboard
                                onCopy={copyTips}
                                text={`${midiRateInfo.lessRate}%`}
                            >
                                <a className='p-x-10' type="link"><CopyOutlined /></a>
                            </CopyToClipboard>
                        </>
                    } type="error"
                    /> : null
            }
            {
                midiRateInfo.moreNum ?
                    <Alert message={
                        <>
                            多弹率：{midiRateInfo.moreRate}%（{midiRateInfo.moreNum}个）
                            <CopyToClipboard
                                onCopy={copyTips}
                                text={`${midiRateInfo.moreRate}%`}
                            >
                                <a className='p-x-10' type="link"><CopyOutlined /></a>
                            </CopyToClipboard>
                        </>
                    } type="error"
                    /> : null
            }
            {
                midiRateInfo.correctNum ?
                    <CopyToClipboard
                        onCopy={copyTips}
                        text={copyAllText}
                    >
                        <a className='p-x-10' type="link"><CopyOutlined /> 复制全部</a>
                    </CopyToClipboard> : null
            }
        </Space>
    ) : null;

    return (
        <div className='p-20'>
            {contextHolder}
            <div>
                <div className="d-flex flex-wrap">
                    <Upload
                        accept={'.mid'}
                        beforeUpload={file => {
                            setMidFile(file);
                            return false;
                        }}
                        className='m-r-20'
                        fileList={midFile ? [midFile] : []}
                        maxCount={1}
                        onRemove={() => setMidFile(null)}
                    >
                        <Button icon={<PlusOutlined />} type="dashed">选择mid文件</Button>
                    </Upload>
                    <Upload
                        accept={'.json'}
                        beforeUpload={file => {
                            setJsonFile(file);
                            return false;
                        }}
                        fileList={jsonFile ? [jsonFile] : []}
                        maxCount={1}
                        onRemove={() => setJsonFile(null)}
                    >
                        <Button icon={<PlusOutlined />} type="dashed">选择json文件</Button>
                    </Upload>
                    <div className={style.input}>
                        <Input.TextArea onChange={e => setJsonUrl(e.target.value)} placeholder="请输入json地址(json文件和地址二选一)"/>
                    </div>
                    <div className='flex-1 d-flex justify-content-end'>
                        <div>
                            <span>时间差音符合并：</span>
                            <Select
                                className='m-r-20'
                                defaultValue={diffTime}
                                onChange={val => setDiffTime(val)}
                                options={diffTimeList}
                                style={{
                                    width: 120,
                                }}
                            />
                        </div>
                        <Button onClick={onDiff} type='primary'>开始对比计算</Button>
                    </div>
                </div>

                <div className='m-t-50 p-t-30' style={{ borderTop: '2px solid #eee' }}>

                    <div className='m-b-20 fz-24'>对比计算结果：</div>
                    {resultNumRate}
                </div>
            </div>
            <div className='m-t-30'>
                <VirtualTable2
                    dataSource={midiList2}
                    scroll={{
                        y: 500,
                        x: 'max-content',
                    }}
                />

            </div>
            {/* mid json对比信息 */}
            <div className='m-t-30'>
                <VirtualTable
                    dataSource={midiList}
                    scroll={{
                        y: 500,
                        x: 'max-content',
                    }}
                />
                <LineEcharts dataSource={chartData}/>
            </div>
        </div>
    );
};

export default MidDiff;
