import { Midi } from '@tonejs/midi';

// 获取mid信息
export const getMidiInfo = async(url, { midStart, midEnd }) => {
    const midiObj = await Midi.fromUrl(url); // midi对象
    console.log(midiObj);
    const notes = []; // 所有音符
    (midiObj?.tracks || []).forEach(track => {
        (track?.notes || []).forEach(note => {
            notes.push(note);
        });
    });
    let starTime = null;
    const result = []; // 结果
    const noteList = notes.sort((a, b) => a.time - b.time);
    const list = noteList.filter((note, i) => {
        return noteList.findIndex(item => (item.time === note.time) && (item.midi === note.midi)) === i; // 去重
    });

    list.splice(list.length - midEnd, list.length); // 去除后面的音符
    list.splice(0, midStart); // 去除前面的音符
    list.forEach((note, i) => { // 按时间排序
        if (starTime === null) {
            starTime = note.time;
        }
        note.originTime = Math.round(note.time * 1000); // 原始时间
        note.start_time = Math.round((note.time - starTime) * 1000); // 转换为0开始 和 ms单位
        result.push(note);
    });
    return {
        notes: result,
    };
};

// 获取json信息
export const getJsonInfo = async(url, { jsonStart, jsonEnd }) => {
    const response = await fetch(url);
    const json = await response.json();
    console.log(json);
    (json.recogniseDataList || []).splice((json.recogniseDataList || []).length - jsonEnd, (json.recogniseDataList || []).length); // 去除后面的音符
    (json.recogniseDataList || []).splice(0, jsonStart); // 去除前面的音符
    const starTime = (json.recogniseDataList || [])[0]?.start_time; // 开始时间
    return {
        notes: (json.recogniseDataList || []).map((note, i) => {
            note.originTime = Math.round(note.start_time / 1000); // 原始时间
            note.start_time = Math.round((note.start_time - starTime) / 1000); // 转换为0开始 和 ms单位
            return note;
        }) || [],
    };
};

// 时间点对比
export const diffJsonMidTime = (midNotes, jsonNotes, diffTime) => {
    const midMaxTime = midNotes[midNotes.length - 1]?.start_time; // mid最大时间
    const jsonMaxTime = jsonNotes[jsonNotes.length - 1]?.start_time; // json最大时间
    jsonNotes.map(item => {
        item.start_time = Math.round(item.start_time * midMaxTime / jsonMaxTime); // 时间按照mid时间比例缩放
        return item;
    });
    const list = midNotes.map(item => {
        jsonNotes.some((jsonItem) => {
            if ((item.start_time - diffTime) <= jsonItem.start_time) {
                if (jsonItem.start_time <= (item.start_time + diffTime)) { // 时间范围内
                    if (!jsonItem.isUse && (jsonItem.note_idx === item.midi)) { // 未使用且音符相同
                        jsonItem.isUse = true; // 标记已使用
                        item.json = jsonItem;
                        return true;
                    }
                }
            }
        });
        return {
            midTime: item.start_time,
            status: item.json?.isUse ? 0 : 1, // 0正确 1少弹 2多弹
            midiNote: item.midi,
            midiName: item.name,
            jsonNote: item.json?.note_idx,
            jsonScore: item.json?.score,
            jsonTime: item.json?.start_time,
        };
    });
    const nums = {
        correctNum: list.filter(({ status }) => status === 0).length, // 正确数
        lessNum: list.filter(({ status }) => status === 1).length, // 少弹数
        moreNum: jsonNotes.filter(({ isUse }) => !isUse).length, // 多弹数
    };
    return {
        list: [
            ...list, // 正确 少弹
            ...jsonNotes.filter(({ isUse }) => !isUse).map(note => ({ // 多弹
                midTime: '无',
                status: 2, // 0正确 1少弹 2多弹
                midiNote: '',
                midiName: '',
                jsonNote: note.note_idx,
                jsonScore: note.score,
                jsonTime: note.start_time,
            })),
        ],
        rate: {
            ...nums,
            correctRate: (nums.correctNum * 100 / midNotes.length).toFixed(2), // 正确率
            lessRate: (nums.lessNum * 100 / midNotes.length).toFixed(2), // 少弹率
            moreRate: (nums.moreNum * 100 / midNotes.length).toFixed(2), // 多弹率
        },
    };
};
