import { Midi } from '@tonejs/midi';

// 获取mid信息
export const getMidiInfo = async(url, diffTime) => {
    const midiObj = await Midi.fromUrl(url); // midi对象
    const notes = []; // 所有音符
    (midiObj?.tracks || []).forEach(track => {
        (track?.notes || []).forEach(note => {
            notes.push(note);
        });
    });
    const result = []; // 结果
    let starTime = 0;
    notes.sort((a, b) => a.time - b.time).forEach((note, i) => { // 按时间排序
        note.time = Math.round(note.time * 1000); // 转换为ms
        if (i === 0) {
            starTime = note.time;
        }
        note.time = note.time - starTime;
        // 合并同一时间的音符
        const prevTime = result[result.length - 1]?.time;
        result[result.length - 1] &&
        ((note.time - prevTime) <= diffTime) ? // 时间差内合并ms
            result[result.length - 1].notes.push(note) : result.push({
                time: note.time,
                notes: [note],
            });
    });
    return {
        result,
        notes,
    };
};

// 获取json信息
export const getJsonInfo = async(url, diffTime) => {
    const response = await fetch(url);
    const json = await response.json();
    const result = []; // 结果
    const starTime = (json.recogniseDataList || [])[0]?.start_time; // 开始时间
    (json.recogniseDataList || []).forEach((note, i) => {
        note.start_time = Math.round((note.start_time - starTime) / 1000); // 转换为ms
        // 合并同一时间段的音符
        const prevTime = result[result.length - 1]?.json_time;
        result[result.length - 1] &&
        ((note.start_time - prevTime) <= diffTime) ? // 时间差内合并ms
            result[result.length - 1].json_notes.push(note) : result.push({
                json_time: note.start_time,
                json_notes: [note],
            });
    });
    return {
        result,
        notes: json.recogniseDataList || [],
    };
};

// 获取音符状态
const getNoteStatus = (midNotes = [], jsonNotes = []) => {
    // json包含mid音符
    const jsonHaveMid = midNotes?.every(midNote => {
        return jsonNotes?.some(({ note_idx }) => note_idx === midNote.midi);
    });
    // mid包含json音符
    const midHaveJson = jsonNotes?.every(jsonNote => {
        return midNotes?.some(({ midi }) => midi === jsonNote.note_idx);
    });
    // json包含mid音符 且 mid包含json音符
    if (jsonHaveMid && midHaveJson) {
        return 0; // 正确
    }
    // json包含mid音符 且 mid不包含json音符
    if (jsonHaveMid && !midHaveJson) {
        return 2; // 多弹
    }
    // json不包含mid音符 且 mid包含json音符
    if (!jsonHaveMid && midHaveJson) {
        return 3; // 少弹
    }
    return 1; // 错弹
};

// mid和json 对比计算 0 正确 1 错弹 2 多弹 3 少弹
export const diffMidJson = (midData, jsonData) => {
    const maxLen = Math.max(midData.length, jsonData.length); // 最大长度
    const result = []; // 结果
    for (let i = 0; i < maxLen; i++) {
        if (midData[i] && jsonData[i]) { // 比较音符存在
            result.push({
                json_time: jsonData[i].json_time,
                time: midData[i].time,
                notes: midData[i].notes,
                json_notes: jsonData[i].json_notes,
                status: getNoteStatus(midData[i].notes, jsonData[i].json_notes),
            });
        } else if (jsonData[i]) { // mid不存在 json存在 为多弹音符
            result.push({
                json_time: jsonData[i].json_time,
                time: '',
                notes: [],
                json_notes: jsonData[i].json_notes,
                status: 2,
            });
        } else if (midData[i]) { // mid存在 json不存在 为少弹音符
            result.push({
                time: midData[i].time,
                notes: midData[i].notes,
                json_notes: [],
                status: 3,
            });
        }
    }
    // 状态数量
    const statusNum = {
        sum: 0,
        correctNum: 0,
        moreNum: 0,
        lessNum: 0,
    };
    for (let i = 0; i < maxLen; i++) {
        if (midData[i] && jsonData[i]) { // 比较音符存在
            statusNum.correctNum += midData[i].notes.filter(({ midi }) => {
                statusNum.sum += 1;
                return jsonData[i].json_notes.some(({ note_idx }) => note_idx === midi); // mid和json都有
            }).length;
            statusNum.lessNum += midData[i].notes.filter(({ midi }) => {
                return !jsonData[i].json_notes.some(({ note_idx }) => note_idx === midi); // mid有 json没有
            }).length;
            statusNum.moreNum += jsonData[i].json_notes.filter(({ note_idx }) => {
                return !midData[i].notes.some(({ midi }) => midi === note_idx); // json有 mid没有
            }).length;
        } else if (jsonData[i]) { // mid不存在 json存在 为多弹音符
            statusNum.moreNum += jsonData[i].json_notes.length;
        } else if (midData[i]) { // mid存在 json不存在 为少弹音符
            statusNum.lessNum += midData[i].notes.length;
            statusNum.sum += midData[i].notes.length;
        }
    }
    return {
        list: result,
        rate: {
            ...statusNum,
            correctRate: (statusNum.correctNum * 100 / statusNum.sum).toFixed(2), // 正确率
            moreRate: (statusNum.moreNum * 100 / statusNum.sum).toFixed(2), // 多弹率
            lessRate: (statusNum.lessNum * 100 / statusNum.sum).toFixed(2), // 少弹率
        },
    };
};

// 处理json数据 少弹 多谈
export const handleJsonLess = (midList, jsonList) => {
    midList.forEach((midItem, i) => {
        if (jsonList[i]) {
            const status = getNoteStatus(midItem.notes, jsonList[i].json_notes);
            if (status === 3) { // 少弹 json少的音符是不是下一个时间段的
                midItem.notes.forEach(midNote => {
                    if (jsonList[i].json_notes.some(({ note_idx }) => note_idx === midNote.midi)) { // 当前时间段是否存在不处理
                        return;
                    }
                    const nextJsonNotes = jsonList[i + 1]?.json_notes;
                    if (nextJsonNotes) {
                        const nextIndex = nextJsonNotes.findIndex(({ note_idx }) => note_idx === midNote.midi);
                        if (nextIndex !== -1) { // 下一个时间段是否存在
                            const nextNote = nextJsonNotes.splice(nextIndex, 1)[0]; // 删除下一个时间段的音符
                            jsonList[i].json_notes.push(nextNote); // 添加到当前时间段
                        }
                    }
                });
                jsonList[i + 1]?.json_notes?.length === 0 && jsonList.splice(i + 1, 1); // 删除空时间段
            } else if (status === 2) { // 多弹 json多的音符是不是下一个时间段的
                jsonList[i].json_notes.forEach((jsonNote, ind) => {
                    if (midList[i]?.notes?.some(({ midi }) => midi === jsonNote.note_idx)) { // 当前时间段是否存在不处理
                        return;
                    }
                    const nextMidNotes = midList[i + 1]?.notes;
                    if (nextMidNotes) {
                        const nextMidIndex = nextMidNotes.findIndex(({ midi }) => midi === jsonNote.note_idx);
                        if (nextMidIndex !== -1) { // 下一个时间段是否存在
                            jsonNote.del = true; // 标记删除
                            if (nextMidNotes.length === 1) { // 下一个时间段只有一个音符 添加下个时间段
                                jsonList.splice(i + 1, 0, {
                                    json_time: jsonNote.start_time,
                                    json_notes: [jsonNote],
                                });
                            } else { // 下一个时间段有多个音符 添加到下个时间段内
                                jsonList[i + 1].json_notes.push(jsonNote);
                            }
                        }
                    }
                });
                jsonList[i].json_notes = jsonList[i].json_notes.filter(({ del }) => !del); // 删除标记删除的音符
            }
        }
    });
};

// 时间点对比
export const diffJsonMidTime = (midNotes, jsonNotes, diffTime) => {
    const midMaxTime = midNotes[midNotes.length - 1]?.time;
    const jsonMaxTime = jsonNotes[jsonNotes.length - 1]?.start_time;
    jsonNotes.map(item => {
        item.start_time = Math.round(item.start_time * midMaxTime / jsonMaxTime);
        return item;
    });
    const result = [];
    let isHaveNum = 0;
    midNotes.map(item => {
        jsonNotes.some((jsonItem) => {
            if ((item.time - diffTime) < jsonItem.start_time) {
                if (jsonItem.start_time < (item.time + diffTime)) { // 时间范围内
                    if (!jsonItem.flag && (jsonItem.note_idx === item.midi)) { // 未使用且音符相同
                        jsonItem.flag = true;
                        isHaveNum += 1;
                        item.json = jsonItem;
                        return true;
                    }
                }
            }
        });
        return item;
    });
    console.log('多弹', jsonNotes.filter(({ flag }) => !flag).length, jsonNotes.filter(({ flag }) => !flag).length / midNotes.length);
    console.log('正确', isHaveNum, isHaveNum / midNotes.length);
    console.log('总数', midNotes.length);
    return midNotes;
};
