
/**
 * Needleman-Wunsch algorithm (内德勒曼-温施算法)
 * 对两条序列进行全局比对的动态规划算法
 */

// 入参如下
// const arr1 = ['2', '1', '3', '3', '3', '1', '8', '7', '9', '7', '6', '3', '4', '5', '8', '7'];
// const arr2 = ['1', '3', '7', '8', '9', '1', '7', '4', '3', '4', '0', '8', '9', '2', '3', '4', '2', '8', '9', '0'];
// 示例用法
// test(arr1, arr2);

// 获取对比结果
export const getDiffResult = (sequence1, sequence2) => {
    sequence1 = sequence1.map((val, i) => i !== sequence1.length - 1 ? `${val},` : val);
    sequence2 = sequence2.map((val, i) => i !== sequence1.length - 1 ? `${val},` : val);
    const matrix = new Array(sequence1.length + 1);
    for (let i = 0; i <= sequence1.length; i++) {
        matrix[i] = new Array(sequence2.length + 1);
        matrix[i][0] = i * -1;
    }

    for (let j = 0; j <= sequence2.length; j++) {
        matrix[0][j] = j * -1;
    }

    for (let i = 1; i <= sequence1.length; i++) {
        for (let j = 1; j <= sequence2.length; j++) {
            const matchScore = sequence1[i - 1] === sequence2[j - 1] ? 1 : -1;
            const diagScore = matrix[i - 1][j - 1] + matchScore;
            const leftScore = matrix[i][j - 1] - 1;
            const upScore = matrix[i - 1][j] - 1;
            matrix[i][j] = Math.max(Math.max(diagScore, leftScore), upScore);
        }
    }
    // console.log(matrix);

    let alignedSequence1 = '';
    let alignedSequence2 = '';
    let i = sequence1.length;
    let j = sequence2.length;
    while (i > 0 || j > 0) {
        if (i > 0 && j > 0 && sequence1[i - 1] === sequence2[j - 1]) {
            alignedSequence1 = sequence1[i - 1] + alignedSequence1;
            alignedSequence2 = sequence2[j - 1] + alignedSequence2;
            i--;
            j--;
        } else if (i > 0 && j > 0 && matrix[i][j] === matrix[i - 1][j - 1] + (sequence1[i - 1] === sequence2[j - 1] ? 1 : -1)) {
            alignedSequence1 = sequence1[i - 1] + alignedSequence1;
            alignedSequence2 = `-,${alignedSequence2}`;
            i--;
        } else if (j > 0 && matrix[i][j] === matrix[i][j - 1] - 1) {
            alignedSequence1 = `-,${alignedSequence1}`;
            alignedSequence2 = sequence2[j - 1] + alignedSequence2;
            j--;
        } else {
            alignedSequence1 = sequence1[i - 1] + alignedSequence1;
            alignedSequence2 = `-,${alignedSequence2}`;
            i--;
        }
    }
    return [alignedSequence1, alignedSequence2];
};

